import Modal from 'flarum/common/components/Modal';
import { tx } from '../util';
import ActivityList from './ActivityList';

/** The board's whole history. */
export default class ActivityModal extends Modal {
  static isDismissibleViaBackdropClick = true;
  className() {
    return 'CorkboardActivityModal';
  }
  title() {
    return tx('board.activity');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(ActivityList, {
      state: this.attrs.board
    }));
  }
}
flarum.reg.add('ernestdefoe-corkboard', 'forum/components/ActivityModal', ActivityModal);